changeSet.sql:
DO $$
DECLARE d DATE := '2026-01-01';
BEGIN
    WHILE d < '2028-01-01' LOOP
        EXECUTE format(
            'CREATE TABLE ${schema_name}.%I PARTITION OF ${schema_name}.STG_INGEST_ERROR FOR VALUES FROM (%L) TO (%L)',
            'STG_INGEST_ERROR_' || to_char(d, 'YYYYMMDD'), d, d + INTERVAL '1 day'
        );
        d := d + INTERVAL '1 day';
    END LOOP;
END;
$$
